fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Assumes tol > 0 by problem specification
    // Promote to i16 to avoid overflow for subtraction and absolute value
    let diff = (a as i16) - (b as i16);
    let tol_i16 = tol as i16;

    diff.abs() < tol_i16
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assume a.len() == b.len() > 0 and tol > 0 as given
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| is_close_i8(x, y, tol))
        .collect()
}